// Резервный SHA ветки main — используется getGithubBranchSha() только в самом
// крайнем случае: если свежий SHA получить не удалось (например, 403 —
// исчерпан лимит 60 запросов/час на IP у api.github.com) И при этом в
// localStorage браузера ещё нет вообще никакого ранее сохранённого SHA
// (первый визит на сайт / очищенный кэш). Раньше в этом случае код подставлял
// имя ветки "main" напрямую в jsDelivr — а jsDelivr кэширует листинг файлов по
// имени ветки на часы без возможности ручного Purge, из-за чего показывались
// давно удалённые треки. Подстановка вот этого константного SHA вместо имени
// ветки гарантирует настоящий (пусть не самый последний) снимок репозитория.
//
// ВАЖНО: обновляйте эту строку на актуальный SHA вашей ветки main каждый раз,
// когда добавляете/удаляете треки в rhythm_game (или стикеры в stickers) —
// иначе в этом редком edge-case будет показываться снимок репозитория на
// момент, когда эта строка была обновлена в последний раз, а не самый свежий.
// Узнать текущий SHA: https://api.github.com/repos/BaksOriginal/movies/git/refs/heads/main
// (поле object.sha) — или, если сам API лимитирует, через
// `git ls-remote https://github.com/BaksOriginal/movies.git main` в терминале.
const GITHUB_FALLBACK_SHA = "cba3258795994c35cea06a41c6269421788c3bc5";

// ==========================================
// АКТУАЛЬНЫЙ SHA ВЕТКИ (обход кэша jsDelivr по "@branch")
// ==========================================
// jsDelivr кэширует ответы по "@main" с заметной задержкой (листинг файлов
// может не обновляться часами после коммита, а ручного Purge для листинга
// data.jsdelivr.com не существует). Ответы же по конкретному commit SHA
// иммутабельны — такой кэш не может "протухнуть": либо там сразу верные
// данные, либо jsDelivr ещё не видел этот SHA и сходит за ним заново.
//
// Поэтому вместо "@main" в URL к data.jsdelivr.com/cdn.jsdelivr.net
// подставляем SHA текущего HEAD ветки. Сам SHA берём с api.github.com —
// это единственное место, где мы всё ещё используем GitHub API напрямую
// (легкий запрос refs/heads, не листинг файлов), и кэшируем результат в
// localStorage на SHA_CACHE_TTL_MS, чтобы не тратить его лимит (60 запросов
// в час на IP) при каждом заходе пользователя на сайт.
const SHA_CACHE_TTL_MS = 30 * 60 * 1000; // 30 минут (было 5 — слишком часто дёргали api.github.com и без нужды приближали лимит 60 запросов/час)

async function getGithubBranchSha(owner, repo, branch) {
    const cacheKey = `ghSha:${owner}/${repo}@${branch}`;
    let cachedEntry = null;
    try {
        const cachedRaw = localStorage.getItem(cacheKey);
        if (cachedRaw) {
            const cached = JSON.parse(cachedRaw);
            if (cached && cached.sha) {
                cachedEntry = cached; // запоминаем даже "протухший" по TTL — пригодится ниже как запасной вариант
                if ((Date.now() - cached.savedAt) < SHA_CACHE_TTL_MS) {
                    return cached.sha;
                }
            }
        }
    } catch (e) { /* битый кэш в localStorage — просто идём за свежим SHA */ }

    try {
        const res = await fetch(`https://api.github.com/repos/${owner}/${repo}/git/refs/heads/${branch}`);
        if (!res.ok) throw new Error("GitHub API вернул статус " + res.status);
        const json = await res.json();
        const sha = json && json.object && json.object.sha;
        if (!sha) throw new Error("Не удалось получить SHA ветки из ответа GitHub API");

        try {
            localStorage.setItem(cacheKey, JSON.stringify({ sha, savedAt: Date.now() }));
        } catch (e) { /* localStorage недоступен/переполнен — не критично, просто не кэшируем */ }

        return sha;
    } catch (e) {
        // Не удалось получить СВЕЖИЙ SHA (лимит GitHub API исчерпан, сеть и
        // т.п.). Раньше здесь был откат сразу на имя ветки ("main") — но
        // именно это один раз и привело к тому, что на сайте показались уже
        // ДАВНО удалённые из GitHub треки: jsDelivr кэширует листинг файлов
        // по имени ветки на часы, и мог отдать старый снимок репозитория
        // (например, от версии до замены Di Young на BenSound).
        //
        // Теперь вместо этого сначала пробуем последний РЕАЛЬНО известный
        // SHA из localStorage, даже если его TTL уже истёк — он указывает
        // на конкретный неизменный коммит, и jsDelivr по нему отдаст пусть
        // не самый свежий, но гарантированно НАСТОЯЩИЙ (когда-то бывший
        // актуальным) снимок репозитория — а не рандомно старый кэш ветки.
        // На имя ветки откатываемся только если вообще никакого SHA нет в
        // кэше (например, самый первый визит на сайт с чистым браузером).
        if (cachedEntry && cachedEntry.sha) {
            console.error(`Не удалось получить свежий SHA ${owner}/${repo}@${branch} (см. ошибку ниже), используем последний известный SHA из кэша:`, e);
            return cachedEntry.sha;
        }

        // Кэш пуст (первый визит/очищенный localStorage) — раньше здесь был
        // откат на имя ветки, что однажды привело к показу давно удалённых
        // треков из-за часового кэша jsDelivr по имени ветки. Теперь вместо
        // этого используем зашитый в коде GITHUB_FALLBACK_SHA — это тоже не
        // самый свежий снимок репозитория, но это гарантированно РЕАЛЬНЫЙ
        // коммит, а не случайно устаревший кэш ветки. Сохраняем его в
        // localStorage как обычный кэш, чтобы при следующем заходе (когда
        // лимит GitHub API уже сбросится) мы попробовали получить свежий SHA
        // заново, а не застряли на fallback навсегда.
        if (GITHUB_FALLBACK_SHA) {
            console.error(`Не удалось получить SHA ветки ${owner}/${repo}@${branch}, и в кэше ничего нет — используем зашитый в коде резервный SHA (${GITHUB_FALLBACK_SHA}):`, e);
            try {
                localStorage.setItem(cacheKey, JSON.stringify({ sha: GITHUB_FALLBACK_SHA, savedAt: Date.now() }));
            } catch (e2) { /* не критично */ }
            return GITHUB_FALLBACK_SHA;
        }

        console.error(`Не удалось получить SHA ветки ${owner}/${repo}@${branch}, и в кэше ничего нет — используем branch напрямую (риск устаревшего кэша jsDelivr):`, e);
        return branch;
    }
}

